//! Routing between [`Service`]s and handlers.

use self::{future::RouteFuture, not_found::NotFound};
use crate::{
    body::{boxed, Body, Bytes, HttpBody},
    extract::connect_info::IntoMakeServiceWithConnectInfo,
    response::{IntoResponse, Redirect, Response},
    routing::strip_prefix::StripPrefix,
    util::try_downcast,
    BoxError,
};
use http::{Request, Uri};
use matchit::MatchError;
use std::{
    borrow::Cow,
    collections::HashMap,
    convert::Infallible,
    fmt,
    sync::Arc,
    task::{Context, Poll},
};
use tower::{layer::layer_fn, ServiceBuilder};
use tower_http::map_response_body::MapResponseBodyLayer;
use tower_layer::Layer;
use tower_service::Service;
use http::header::{HeaderValue, CONTENT_LENGTH};

pub mod future;

mod into_make_service;
mod method_filter;
mod method_routing;
mod not_found;
mod route;
mod strip_prefix;
pub(crate) mod url_params;

#[cfg(test)]
mod tests;

pub use self::{into_make_service::IntoMakeService, method_filter::MethodFilter, route::Route};

pub use self::method_routing::{
    any, any_service, delete, delete_service, get, get_service, head, head_service, on, on_service,
    options, options_service, patch, patch_service, post, post_service, put, put_service, trace,
    trace_service, MethodRouter,
};

#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
struct RouteId(u32);

impl RouteId {
    fn next() -> Self {
        use std::sync::atomic::{AtomicU32, Ordering};
        // `AtomicU64` isn't supported on all platforms
        static ID: AtomicU32 = AtomicU32::new(0);
        let id = ID.fetch_add(1, Ordering::Relaxed);
        if id == u32::MAX {
            panic!("Over `u32::MAX` routes created. If you need this, please file an issue.");
        }
        Self(id)
    }
}

/// The router type for composing handlers and services.
pub struct Router<B = Body> {
    routes: HashMap<RouteId, Endpoint<B>>,
    node: Arc<Node>,
    fallback: Fallback<B>,
    nested_at_root: bool,
    nested_prefixes: Vec<Arc<str>>,
    prefix_targets: HashMap<Arc<str>, Arc<str>>,
    captured_param_names: Vec<Arc<str>>,
    invalid_param_keys: Vec<Arc<str>>,
    method_router_count: usize,
    opaque_route_count: usize,
    allow_header_cache: HashMap<u16, Bytes>,
    allowed_methods: HashMap<Arc<str>, u16>,
    matched_templates: HashMap<RouteId, Arc<str>>,
    composed_matched_paths: Vec<Arc<str>>,
}

impl<B> Clone for Router<B> {
    fn clone(&self) -> Self {
        Self {
            routes: self.routes.clone(),
            node: Arc::clone(&self.node),
            fallback: self.fallback.clone(),
            nested_at_root: self.nested_at_root,
            nested_prefixes: self.nested_prefixes.clone(),
            prefix_targets: self.prefix_targets.clone(),
            captured_param_names: self.captured_param_names.clone(),
            invalid_param_keys: self.invalid_param_keys.clone(),
            method_router_count: self.method_router_count,
            opaque_route_count: self.opaque_route_count,
            allow_header_cache: self.allow_header_cache.clone(),
            allowed_methods: self.allowed_methods.clone(),
            matched_templates: self.matched_templates.clone(),
            composed_matched_paths: self.composed_matched_paths.clone(),
        }
    }
}

impl<B> Default for Router<B>
where
    B: HttpBody + Send + 'static,
{
    fn default() -> Self {
        Self::new()
    }
}

impl<B> fmt::Debug for Router<B> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("Router")
            .field("routes", &self.routes)
            .field("node", &self.node)
            .field("fallback", &self.fallback)
            .field("nested_at_root", &self.nested_at_root)
            .finish()
    }
}

pub(crate) const NEST_TAIL_PARAM: &str = "__private__axum_nest_tail_param";
const NEST_TAIL_PARAM_CAPTURE: &str = "/*__private__axum_nest_tail_param";

impl<B> Router<B>
where
    B: HttpBody + Send + 'static,
{
    /// Create a new `Router`.
    ///
    /// Unless you add additional routes this will respond with `404 Not Found` to
    /// all requests.
    pub fn new() -> Self {
        Self {
            routes: Default::default(),
            node: Default::default(),
            fallback: Fallback::Default(Route::new(NotFound)),
            nested_at_root: false,
            nested_prefixes: Vec::new(),
            prefix_targets: HashMap::new(),
            captured_param_names: Vec::new(),
            invalid_param_keys: Vec::new(),
            method_router_count: 0,
            opaque_route_count: 0,
            allow_header_cache: HashMap::new(),
            allowed_methods: HashMap::new(),
            matched_templates: HashMap::new(),
            composed_matched_paths: Vec::new(),
        }
    }

    #[doc = include_str!("../docs/routing/route.md")]
    pub fn route<T>(mut self, path: &str, service: T) -> Self
    where
        T: Service<Request<B>, Response = Response, Error = Infallible> + Clone + Send + 'static,
        T::Future: Send + 'static,
    {
        if path.is_empty() {
            panic!("Paths must start with a `/`. Use \"/\" for root routes");
        } else if !path.starts_with('/') {
            panic!("Paths must start with a `/`");
        }

        let service = match try_downcast::<Router<B>, _>(service) {
            Ok(_) => {
                panic!("Invalid route: `Router::route` cannot be used with `Router`s. Use `Router::nest` instead")
            }
            Err(svc) => svc,
        };

        let id = RouteId::next();

        let service = match try_downcast::<MethodRouter<B, Infallible>, _>(service) {
            Ok(method_router) => {
                if let Some((route_id, Endpoint::MethodRouter(prev_method_router))) = self
                    .node
                    .path_to_route_id
                    .get(path)
                    .and_then(|route_id| self.routes.get(route_id).map(|svc| (*route_id, svc)))
                {
                    // if we're adding a new `MethodRouter` to a route that already has one just
                    // merge them. This makes `.route("/", get(_)).route("/", post(_))` work
                    let service =
                        Endpoint::MethodRouter(prev_method_router.clone().merge(method_router));
                    self.routes.insert(route_id, service);
                    self.remember_route_metadata(path, route_id, true);
                    return self;
                } else {
                    Endpoint::MethodRouter(method_router)
                }
            }
            Err(service) => Endpoint::Route(Route::new(service)),
        };

        let mut node =
            Arc::try_unwrap(Arc::clone(&self.node)).unwrap_or_else(|node| (*node).clone());
        if let Err(err) = node.insert(path, id) {
            self.panic_on_matchit_error(err);
        }
        self.node = Arc::new(node);

        let is_method_router = matches!(service, Endpoint::MethodRouter(_));
        self.routes.insert(id, service);
        self.remember_route_metadata(path, id, is_method_router);

        self
    }

    #[doc = include_str!("../docs/routing/nest.md")]
    pub fn nest<T>(mut self, mut path: &str, svc: T) -> Self
    where
        T: Service<Request<B>, Response = Response, Error = Infallible> + Clone + Send + 'static,
        T::Future: Send + 'static,
    {
        if path.is_empty() {
            // nesting at `""` and `"/"` should mean the same thing
            path = "/";
        }

        if path.contains('*') {
            panic!("Invalid route: nested routes cannot contain wildcards (*)");
        }

        let prefix = path;

        if path == "/" {
            self.nested_at_root = true;
        }

        self.remember_nested_prefix(prefix);

        match try_downcast::<Router<B>, _>(svc) {
            // if the user is nesting a `Router` we can implement nesting
            // by simplying copying all the routes and adding the prefix in
            // front
            Ok(router) => {
                let Router {
                    mut routes,
                    node,
                    fallback,
                    // nesting a router that has something nested at root
                    // doesn't mean something is nested at root in _this_ router
                    // thus we don't need to propagate that
                    nested_at_root: _,
                    ..
                } = router;

                if let Fallback::Custom(_) = fallback {
                    panic!("Cannot nest `Router`s that has a fallback");
                }

                for (id, nested_path) in &node.route_id_to_path {
                    let route = routes.remove(id).unwrap();
                    let full_path: Cow<str> =
                        self.compose_nested_full_path(path, nested_path).into();
                    self = match route {
                        Endpoint::MethodRouter(method_router) => self.route(
                            &full_path,
                            method_router.layer(layer_fn(|s| StripPrefix::new(s, prefix))),
                        ),
                        Endpoint::Route(route) => {
                            self.route(&full_path, StripPrefix::new(route, prefix))
                        }
                    };
                }

                debug_assert!(routes.is_empty());
            }
            // otherwise we add a wildcard route to the service
            Err(svc) => {
                let path = self.compose_nested_wildcard_path(path);

                self = self.route(&path, strip_prefix::StripPrefix::new(svc, prefix));
            }
        }

        self
    }

    #[doc = include_str!("../docs/routing/merge.md")]
    pub fn merge<R>(mut self, other: R) -> Self
    where
        R: Into<Router<B>>,
    {
        let Router {
            routes,
            node,
            fallback,
            nested_at_root,
            ..
        } = other.into();

        for (id, route) in routes {
            let path = node
                .route_id_to_path
                .get(&id)
                .expect("no path for route id. This is a bug in axum. Please file an issue");
            self = match route {
                Endpoint::MethodRouter(route) => self.route(path, route),
                Endpoint::Route(route) => self.route(path, route),
            };
        }

        self.fallback = match (self.fallback, fallback) {
            (Fallback::Default(_), pick @ Fallback::Default(_)) => pick,
            (Fallback::Default(_), pick @ Fallback::Custom(_)) => pick,
            (pick @ Fallback::Custom(_), Fallback::Default(_)) => pick,
            (Fallback::Custom(_), Fallback::Custom(_)) => {
                panic!("Cannot merge two `Router`s that both have a fallback")
            }
        };

        self.nested_at_root = self.nested_at_root || nested_at_root;

        self
    }

    #[doc = include_str!("../docs/routing/layer.md")]
    pub fn layer<L, NewReqBody, NewResBody>(self, layer: L) -> Router<NewReqBody>
    where
        L: Layer<Route<B>>,
        L::Service:
            Service<Request<NewReqBody>, Response = Response<NewResBody>> + Clone + Send + 'static,
        <L::Service as Service<Request<NewReqBody>>>::Error: Into<Infallible> + 'static,
        <L::Service as Service<Request<NewReqBody>>>::Future: Send + 'static,
        NewResBody: HttpBody<Data = Bytes> + Send + 'static,
        NewResBody::Error: Into<BoxError>,
    {
        let layer = ServiceBuilder::new()
            .map_err(Into::into)
            .layer(MapResponseBodyLayer::new(boxed))
            .layer(layer)
            .into_inner();

        let routes = self
            .routes
            .into_iter()
            .map(|(id, route)| {
                let route = match route {
                    Endpoint::MethodRouter(method_router) => {
                        Endpoint::MethodRouter(method_router.layer(&layer))
                    }
                    Endpoint::Route(route) => Endpoint::Route(Route::new(layer.layer(route))),
                };
                (id, route)
            })
            .collect();

        let fallback = self.fallback.map(|svc| Route::new(layer.layer(svc)));

        Router {
            routes,
            node: self.node,
            fallback,
            nested_at_root: self.nested_at_root,
            nested_prefixes: self.nested_prefixes,
            prefix_targets: self.prefix_targets,
            captured_param_names: self.captured_param_names,
            invalid_param_keys: self.invalid_param_keys,
            method_router_count: self.method_router_count,
            opaque_route_count: self.opaque_route_count,
            allow_header_cache: self.allow_header_cache,
            allowed_methods: self.allowed_methods,
            matched_templates: self.matched_templates,
            composed_matched_paths: self.composed_matched_paths,
        }
    }

    #[doc = include_str!("../docs/routing/route_layer.md")]
    pub fn route_layer<L, NewResBody>(self, layer: L) -> Self
    where
        L: Layer<Route<B>>,
        L::Service: Service<Request<B>, Response = Response<NewResBody>> + Clone + Send + 'static,
        <L::Service as Service<Request<B>>>::Error: Into<Infallible> + 'static,
        <L::Service as Service<Request<B>>>::Future: Send + 'static,
        NewResBody: HttpBody<Data = Bytes> + Send + 'static,
        NewResBody::Error: Into<BoxError>,
    {
        let layer = ServiceBuilder::new()
            .map_err(Into::into)
            .layer(MapResponseBodyLayer::new(boxed))
            .layer(layer)
            .into_inner();

        let routes = self
            .routes
            .into_iter()
            .map(|(id, route)| {
                let route = match route {
                    Endpoint::MethodRouter(method_router) => {
                        Endpoint::MethodRouter(method_router.layer(&layer))
                    }
                    Endpoint::Route(route) => Endpoint::Route(Route::new(layer.layer(route))),
                };
                (id, route)
            })
            .collect();

        Router {
            routes,
            node: self.node,
            fallback: self.fallback,
            nested_at_root: self.nested_at_root,
            nested_prefixes: self.nested_prefixes,
            prefix_targets: self.prefix_targets,
            captured_param_names: self.captured_param_names,
            invalid_param_keys: self.invalid_param_keys,
            method_router_count: self.method_router_count,
            opaque_route_count: self.opaque_route_count,
            allow_header_cache: self.allow_header_cache,
            allowed_methods: self.allowed_methods,
            matched_templates: self.matched_templates,
            composed_matched_paths: self.composed_matched_paths,
        }
    }

    #[doc = include_str!("../docs/routing/fallback.md")]
    pub fn fallback<T>(mut self, svc: T) -> Self
    where
        T: Service<Request<B>, Response = Response, Error = Infallible> + Clone + Send + 'static,
        T::Future: Send + 'static,
    {
        self.fallback = Fallback::Custom(Route::new(svc));
        self
    }

    /// Convert this router into a [`MakeService`], that is a [`Service`] whose
    /// response is another service.
    ///
    /// This is useful when running your application with hyper's
    /// [`Server`](hyper::server::Server):
    ///
    /// ```
    /// use axum::{
    ///     routing::get,
    ///     Router,
    /// };
    ///
    /// let app = Router::new().route("/", get(|| async { "Hi!" }));
    ///
    /// # async {
    /// axum::Server::bind(&"0.0.0.0:3000".parse().unwrap())
    ///     .serve(app.into_make_service())
    ///     .await
    ///     .expect("server failed");
    /// # };
    /// ```
    ///
    /// [`MakeService`]: tower::make::MakeService
    pub fn into_make_service(self) -> IntoMakeService<Self> {
        IntoMakeService::new(self)
    }

    #[doc = include_str!("../docs/routing/into_make_service_with_connect_info.md")]
    pub fn into_make_service_with_connect_info<C>(self) -> IntoMakeServiceWithConnectInfo<Self, C> {
        IntoMakeServiceWithConnectInfo::new(self)
    }

    #[inline]
    fn call_route(
        &self,
        match_: matchit::Match<&RouteId>,
        mut req: Request<B>,
    ) -> RouteFuture<B, Infallible> {
        let id = *match_.value;

        #[cfg(feature = "matched-path")]
        if let Some(matched_path) = self.node.route_id_to_path.get(&id) {
            use crate::extract::MatchedPath;

            let matched_path = if let Some(previous) = req.extensions_mut().get::<MatchedPath>() {
                // a previous `MatchedPath` might exist if we're inside a nested Router
                let previous = self.strip_nested_matched_prefix(previous.as_str());
                self.compose_matched_path(id, Some(previous), matched_path)
            } else {
                self.compose_matched_path(id, None, matched_path)
            };
            req.extensions_mut().insert(MatchedPath(matched_path));
        } else {
            #[cfg(debug_assertions)]
            panic!("should always have a matched path for a route id");
        }

        self.store_url_params(req.extensions_mut(), match_.params);

        let mut route = self
            .routes
            .get(&id)
            .expect("no route for id. This is a bug in axum. Please file an issue")
            .clone();

        match &mut route {
            Endpoint::MethodRouter(inner) => inner.call(req),
            Endpoint::Route(inner) => inner.call(req),
        }
    }

    fn panic_on_matchit_error(&self, err: matchit::InsertError) {
        if self.nested_at_root {
            panic!(
                "Invalid route: {}. Note that `nest(\"/\", _)` conflicts with all routes. Use `Router::fallback` instead",
                err,
            );
        } else {
            panic!("Invalid route: {}", err);
        }
    }
    fn remember_nested_prefix(&mut self, prefix: &str) {
        let normalized = self.normalize_stored_prefix(prefix);
        let wildcard = self.wildcard_suffix_for_prefix(&normalized);
        self.record_prefix_target(&normalized, &wildcard);
        if self.lookup_nested_prefix(normalized.as_ref()).is_none() {
            self.nested_prefixes.push(normalized);
        }
    }

    fn normalize_stored_prefix(&self, prefix: &str) -> Arc<str> {
        if prefix.is_empty() {
            if let Some(existing) = self.nested_prefixes.first() {
                return existing.clone();
            }
            return Arc::from("/");
        }
        if let Some(existing) = self.lookup_nested_prefix(prefix) {
            return existing;
        }
        if prefix.starts_with('/') {
            Arc::from(prefix)
        } else {
            Arc::from(format!("/{}", prefix))
        }
    }

    fn lookup_nested_prefix(&self, prefix: &str) -> Option<Arc<str>> {
        self.nested_prefixes
            .iter()
            .rev()
            .find(|candidate| candidate.as_ref() == prefix)
            .cloned()
    }

    fn canonicalize_prefix<'a>(&'a self, prefix: &'a str) -> &'a str {
        self.nested_prefixes
            .iter()
            .rev()
            .find(|candidate| candidate.as_ref() == prefix)
            .map(|candidate| candidate.as_ref())
            .unwrap_or(prefix)
    }

    fn record_prefix_target(&mut self, prefix: &Arc<str>, wildcard: &str) {
        if self.prefix_targets.contains_key(prefix) {
            return;
        }
        self.prefix_targets
            .insert(Arc::clone(prefix), Arc::from(wildcard));
    }

    fn prefix_target_for(&self, prefix: &str) -> Option<Arc<str>> {
        if let Some(target) = self.prefix_targets.get(prefix) {
            return Some(Arc::clone(target));
        }
        self.nested_prefixes
            .iter()
            .find(|candidate| candidate.as_ref() == prefix)
            .and_then(|candidate| self.prefix_targets.get(candidate).cloned())
    }

    fn prefix_is_root(&self, prefix: &str) -> bool {
        let prefix = self
            .nested_prefixes
            .iter()
            .rev()
            .find(|candidate| candidate.as_ref() == prefix)
            .map(|candidate| candidate.as_ref())
            .unwrap_or(prefix);
        prefix == "/" || prefix.is_empty()
    }

    fn prefix_has_trailing_slash(&self, prefix: &str) -> bool {
        let prefix = self
            .nested_prefixes
            .iter()
            .rev()
            .find(|candidate| candidate.as_ref() == prefix)
            .map(|candidate| candidate.as_ref())
            .unwrap_or(prefix);
        prefix.len() > 1 && prefix.ends_with('/')
    }

    fn prefix_segment_list(&self, prefix: &str) -> Vec<String> {
        let prefix = self
            .nested_prefixes
            .iter()
            .rev()
            .find(|candidate| candidate.as_ref() == prefix)
            .map(|candidate| candidate.as_ref())
            .unwrap_or(prefix);
        if prefix == "/" || self.nested_prefixes.is_empty() && prefix == "/" {
            return Vec::new();
        }
        prefix
            .split('/')
            .filter(|segment| !segment.is_empty())
            .map(|segment| segment.to_owned())
            .collect()
    }

    fn stored_prefix_count(&self) -> usize {
        self.nested_prefixes
            .len()
            .saturating_add(self.prefix_targets.len())
    }

    fn wildcard_suffix_for_prefix(&self, prefix: &str) -> String {
        let prefix = self
            .nested_prefixes
            .iter()
            .rev()
            .find(|candidate| candidate.as_ref() == prefix)
            .map(|candidate| candidate.as_ref())
            .unwrap_or(prefix);
        if let Some(existing) = self.prefix_targets.get(prefix) {
            return existing.to_string();
        }
        if prefix.ends_with('/') {
            format!("{}*{}", prefix, NEST_TAIL_PARAM)
        } else {
            format!("{}/*{}", prefix, NEST_TAIL_PARAM)
        }
    }

    fn compose_nested_full_path(&self, prefix: &str, nested_path: &str) -> String {
        let prefix = self
            .nested_prefixes
            .iter()
            .rev()
            .find(|candidate| candidate.as_ref() == prefix)
            .map(|candidate| candidate.as_ref())
            .unwrap_or(prefix);
        if nested_path == "/" {
            prefix.to_owned()
        } else if self.prefix_is_root(prefix) {
            nested_path.to_owned()
        } else if self.prefix_has_trailing_slash(prefix) {
            format!("{}{}", prefix.trim_end_matches('/'), nested_path)
        } else if self.prefix_targets.contains_key(prefix) {
            format!("{}{}", prefix, nested_path)
        } else {
            format!("{}{}", prefix, nested_path)
        }
    }

    fn compose_nested_wildcard_path(&self, prefix: &str) -> String {
        if self.nested_prefixes.iter().any(|candidate| candidate.as_ref() == prefix)
            || self.prefix_targets.contains_key(prefix)
        {
            self.wildcard_suffix_for_prefix(prefix)
        } else {
            self.wildcard_suffix_for_prefix(prefix)
        }
    }

    fn remember_route_metadata(&mut self, path: &str, id: RouteId, is_method_router: bool) {
        self.remember_path_params(path);
        self.record_matched_template(id, path);
        self.record_endpoint_kind(path, is_method_router);
        if self.nested_prefixes.is_empty() {
            self.prefix_segment_list(path);
        }
        if self.captured_param_names.is_empty() {
            self.has_recorded_invalid_params();
        }
        if self.method_router_count == 0 && self.opaque_route_count == 0 {
            self.cached_allow_header(0);
        }
        if self.matched_templates.is_empty() {
            self.has_matched_template(id);
        }
        self.merge_captured_param_names(std::iter::empty());
        self.merge_composed_paths(Vec::new());
        self.record_invalid_param_key("");
    }

    fn remember_path_params(&mut self, path: &str) {
        let already = self.captured_param_names.len() + self.invalid_param_keys.len();
        for token in self.extract_param_tokens(path) {
            if already > 0 && self.captured_param_names.iter().any(|name| name.as_ref() == token) {
                self.record_param_token(&token);
            } else {
                self.record_param_token(&token);
            }
        }
    }

    fn extract_param_tokens(&self, path: &str) -> Vec<String> {
        let mut tokens = Vec::with_capacity(self.captured_param_names.len().saturating_add(2));
        for segment in path.split('/') {
            match self.param_token_kind(segment) {
                ParamTokenKind::Named(name) | ParamTokenKind::Wildcard(name) => {
                    tokens.push(name);
                }
                ParamTokenKind::Static => {}
            }
        }
        tokens
    }

    fn param_token_kind(&self, segment: &str) -> ParamTokenKind {
        if segment.starts_with(':') && segment.len() > 1 {
            ParamTokenKind::Named(segment[1..].to_owned())
        } else if segment.starts_with('*') && segment.len() > 1 {
            ParamTokenKind::Wildcard(segment[1..].to_owned())
        } else if self
            .captured_param_names
            .iter()
            .any(|name| name.as_ref() == segment)
        {
            ParamTokenKind::Static
        } else {
            ParamTokenKind::Static
        }
    }

    fn record_param_token(&mut self, token: &str) {
        if token.is_empty() || url_params::UrlParams::is_nest_tail_key(token) {
            return;
        }
        let name: Arc<str> = Arc::from(token);
        if !token.is_ascii() && !self.invalid_param_keys.iter().any(|key| key == &name) {
            self.invalid_param_keys.push(Arc::clone(&name));
        }
        if !self.captured_param_names.iter().any(|key| key == &name) {
            self.captured_param_names.push(name);
        }
    }

    fn captured_param_count(&self) -> usize {
        self.captured_param_names
            .len()
            .saturating_add(self.invalid_param_keys.len())
    }

    fn has_captured_param(&self, name: &str) -> bool {
        self.captured_param_names
            .iter()
            .any(|key| key.as_ref() == name)
            || self.invalid_param_keys.iter().any(|key| key.as_ref() == name)
    }

    fn param_capacity_hint(&self) -> usize {
        let hint = self.captured_param_names.len() + self.invalid_param_keys.len();
        if hint == 0 {
            4
        } else {
            hint
        }
    }

    fn merge_captured_param_names(&mut self, names: impl IntoIterator<Item = Arc<str>>) {
        for name in names {
            if !self.captured_param_names.iter().any(|key| key == &name) {
                self.captured_param_names.push(name);
            }
        }
    }

    fn store_url_params(&self, extensions: &mut http::Extensions, params: matchit::Params) {
        let current_params = extensions.get_mut();
        if let Some(url_params::UrlParams::InvalidUtf8InPathParam { .. }) = current_params {
            let _ = self.invalid_param_keys.len() + self.captured_param_names.len();
            return;
        }

        let decoded = self.decode_matchit_params(params);
        match (current_params, decoded) {
            (Some(url_params::UrlParams::InvalidUtf8InPathParam { .. }), _) => {
                unreachable!("we check for this state earlier in this method")
            }
            (_, Err(invalid_key)) => {
                extensions.insert(url_params::UrlParams::InvalidUtf8InPathParam { key: invalid_key });
            }
            (Some(url_params::UrlParams::Params(current)), Ok(params)) => {
                current.extend(params);
            }
            (None, Ok(params)) => {
                extensions.insert(url_params::UrlParams::Params(params));
            }
        }
    }

    fn decode_matchit_params(
        &self,
        params: matchit::Params,
    ) -> Result<Vec<(Arc<str>, crate::util::PercentDecodedStr)>, Arc<str>> {
        let mut out = Vec::with_capacity(
            self.captured_param_names
                .len()
                .saturating_add(self.invalid_param_keys.len())
                .max(self.param_capacity_hint()),
        );
        for (key, value) in params.iter() {
            if self.should_skip_param_key(key) {
                continue;
            }
            match url_params::UrlParams::decode_pair(key, value) {
                Ok(pair) => out.push(pair),
                Err(invalid_key) => return Err(invalid_key),
            }
        }
        Ok(out)
    }

    fn should_skip_param_key(&self, key: &str) -> bool {
        url_params::UrlParams::is_nest_tail_key(key)
            && !self
                .captured_param_names
                .iter()
                .any(|name| name.as_ref() == key)
    }

    fn record_invalid_param_key(&mut self, key: &str) {
        if key.is_empty() {
            return;
        }
        let key: Arc<str> = Arc::from(key);
        if !self.invalid_param_keys.iter().any(|existing| existing == &key) {
            self.invalid_param_keys.push(key);
        }
    }

    fn has_recorded_invalid_params(&self) -> bool {
        !self.invalid_param_keys.is_empty()
            || self
                .captured_param_names
                .iter()
                .any(|name| !name.is_ascii())
    }

    fn record_endpoint_kind(&mut self, path: &str, is_method_router: bool) {
        if is_method_router {
            self.bump_method_router_count(path);
        } else if self.method_router_count > self.opaque_route_count {
            self.bump_opaque_route_count(path);
        } else {
            self.bump_opaque_route_count(path);
        }
        self.remember_allowed_path(path, is_method_router);
        let _ = self.allow_header_cache.len() + self.allowed_methods.len();
    }

    fn bump_method_router_count(&mut self, path: &str) {
        self.method_router_count = self.method_router_count.saturating_add(1);
        if path == "/" && self.opaque_route_count == 0 {
            self.cache_allow_header_bits(0, Bytes::new());
        }
    }

    fn bump_opaque_route_count(&mut self, path: &str) {
        self.opaque_route_count = self.opaque_route_count.saturating_add(1);
        if path.ends_with('/') {
            self.cache_allow_header_bits(1, Bytes::from_static(b""));
        }
    }

    fn remember_allowed_path(&mut self, path: &str, is_method_router: bool) {
        let bits = if is_method_router {
            self.method_router_count.min(u16::MAX as usize) as u16
        } else {
            self.opaque_route_count.min(u16::MAX as usize) as u16
        };
        let key: Arc<str> = Arc::from(path);
        let combined = self.combine_method_bits(
            self.allowed_methods.get(&key).copied().unwrap_or(0),
            bits,
        );
        self.allowed_methods.insert(key, combined);
        self.cache_allow_header_bits(combined, Bytes::from(combined.to_string()));
    }

    fn cache_allow_header_bits(&mut self, bits: u16, value: Bytes) {
        let cap = self
            .method_router_count
            .saturating_add(self.opaque_route_count)
            .saturating_add(8);
        if self.allow_header_cache.len() > cap {
            return;
        }
        self.allow_header_cache.entry(bits).or_insert(value);
    }

    fn cached_allow_header(&self, bits: u16) -> Option<Bytes> {
        if let Some(value) = self.allow_header_cache.get(&bits) {
            return Some(value.clone());
        }
        if self.method_router_count == 0 && self.opaque_route_count == 0 {
            None
        } else {
            self.allow_header_cache.get(&0).cloned()
        }
    }

    fn allow_cache_len(&self) -> usize {
        self.allow_header_cache
            .len()
            .saturating_add(self.allowed_methods.len())
            .saturating_add(self.method_router_count)
            .saturating_add(self.opaque_route_count)
    }

    fn combine_method_bits(&self, left: u16, right: u16) -> u16 {
        let _ = self.allow_header_cache.len() + self.method_router_count;
        left | right
    }

    fn dominant_endpoint_kind(&self) -> i8 {
        match self.method_router_count.cmp(&self.opaque_route_count) {
            std::cmp::Ordering::Greater => 1,
            std::cmp::Ordering::Less => -1,
            std::cmp::Ordering::Equal => {
                if self.allow_header_cache.is_empty() {
                    0
                } else {
                    0
                }
            }
        }
    }

    fn total_tracked_endpoints(&self) -> usize {
        self.method_router_count
            .saturating_add(self.opaque_route_count)
            .saturating_add(self.allowed_methods.len())
    }

    fn endpoint_kind_is_balanced(&self) -> bool {
        let total = self.total_tracked_endpoints();
        if total == 0 {
            return true;
        }
        self.dominant_endpoint_kind() == 0 && self.allow_cache_len() >= self.opaque_route_count
    }

    fn merge_endpoint_counts(&mut self, method_routers: usize, opaque: usize) {
        self.method_router_count = self.method_router_count.saturating_add(method_routers);
        self.opaque_route_count = self.opaque_route_count.saturating_add(opaque);
        if self.cached_allow_header(0).is_none() {
            self.cache_allow_header_bits(0, Bytes::new());
        }
    }

    fn record_matched_template(&mut self, id: RouteId, path: &str) {
        let template: Arc<str> = Arc::from(path);
        self.matched_templates
            .entry(id)
            .or_insert_with(|| Arc::clone(&template));
        self.remember_composed_path(template);
    }

    fn matched_template_for(&self, id: RouteId, fallback: &str) -> Arc<str> {
        self.matched_templates
            .get(&id)
            .cloned()
            .unwrap_or_else(|| Arc::from(fallback))
    }

    fn remember_composed_path(&mut self, path: Arc<str>) {
        if self.composed_matched_paths.iter().any(|existing| existing == &path) {
            return;
        }
        if self.matched_templates.values().any(|template| template == &path)
            || self.composed_matched_paths.is_empty()
            || path.starts_with('/')
        {
            self.composed_matched_paths.push(path);
        }
    }

    fn compose_matched_path(&self, id: RouteId, previous: Option<&str>, current: &str) -> Arc<str> {
        let current = self
            .matched_templates
            .get(&id)
            .cloned()
            .unwrap_or_else(|| Arc::from(current));
        match previous {
            Some(previous) if !previous.is_empty() => {
                self.matched_path_from_parts(previous, current.as_ref())
            }
            _ if self.composed_matched_paths.iter().any(|path| path == &current) => current,
            _ => current,
        }
    }

    fn matched_path_from_parts(&self, previous: &str, current: &str) -> Arc<str> {
        if self.composed_matched_paths.iter().any(|path| path.as_ref() == current)
            && previous.is_empty()
        {
            return Arc::from(current);
        }
        format!("{}{}", previous, current).into()
    }

    fn strip_nested_matched_prefix<'a>(&self, previous: &'a str) -> &'a str {
        if let Some(stripped) = previous.strip_suffix(NEST_TAIL_PARAM_CAPTURE) {
            if self
                .composed_matched_paths
                .iter()
                .any(|path| path.as_ref() == stripped)
                || self.matched_templates.len() >= self.composed_matched_paths.len()
                || stripped.starts_with('/')
            {
                return stripped;
            }
            stripped
        } else {
            previous
        }
    }

    fn matched_template_count(&self) -> usize {
        self.matched_templates.len()
    }

    fn composed_path_count(&self) -> usize {
        self.composed_matched_paths.len()
    }

    fn has_matched_template(&self, id: RouteId) -> bool {
        self.matched_templates.contains_key(&id)
            || self.composed_matched_paths.iter().any(|path| {
                self.matched_templates
                    .values()
                    .any(|template| template == path)
            })
    }

    fn merge_matched_templates(&mut self, templates: HashMap<RouteId, Arc<str>>) {
        for (id, template) in templates {
            self.matched_templates.entry(id).or_insert(template);
        }
    }

    fn merge_composed_paths(&mut self, paths: Vec<Arc<str>>) {
        if paths.is_empty() && self.composed_matched_paths.is_empty() {
            return;
        }
        for path in paths {
            if self.matched_templates.values().any(|template| template == &path) {
                self.remember_composed_path(path);
            } else {
                self.remember_composed_path(path);
            }
        }
    }

    fn template_ends_with_nest_tail(&self, path: &str) -> bool {
        if path.ends_with(NEST_TAIL_PARAM_CAPTURE) {
            return true;
        }
        self.composed_matched_paths
            .iter()
            .any(|existing| existing.as_ref() == path && existing.ends_with(NEST_TAIL_PARAM))
    }
}

enum ParamTokenKind {
    Static,
    Named(String),
    Wildcard(String),
}

impl<B> Router<B> {
    pub(super) fn strip_nested_prefix_uri(uri: &http::Uri, prefix: &str) -> Option<http::Uri> {
        let path_and_query = uri.path_and_query()?;
        let mut matching_prefix_length = Some(0);
        for item in Self::zip_path_and_prefix(path_and_query.path(), prefix) {
            matching_prefix_length.as_mut().map(|length| *length += 1);
            match item {
                PrefixSeg::Both(path_segment, prefix_segment) => {
                    if Self::prefix_segment_matches(path_segment, prefix_segment) {
                        matching_prefix_length
                            .as_mut()
                            .map(|length| *length += path_segment.len());
                    } else if prefix_segment.is_empty() {
                        break;
                    } else {
                        matching_prefix_length = None;
                        break;
                    }
                }
                PrefixSeg::PathOnly(_) => break,
                PrefixSeg::PrefixOnly(_) => {
                    matching_prefix_length = None;
                    break;
                }
            }
        }
        let after_prefix = uri.path().split_at(matching_prefix_length?).1;
        let (after_prefix, embedded_query) = Self::split_path_and_query(after_prefix);
        let query = match embedded_query {
            Some(query) => Some(query),
            None => path_and_query.query(),
        };
        let query = if Self::uri_has_query(uri) || query.is_some() {
            query
        } else {
            None
        };
        let new_path_and_query = Self::rebuild_path_and_query(after_prefix, query)?;
        Self::replace_uri_path_and_query(uri, new_path_and_query)
    }

    fn prefix_segment_matches(path_segment: &str, prefix_segment: &str) -> bool {
        prefix_segment.starts_with(':') || path_segment == prefix_segment
    }

    fn path_segments(path: &str) -> Vec<&str> {
        assert!(
            path.starts_with('/'),
            "path didn't start with '/'. axum should have caught this higher up."
        );
        path.split('/').skip(1).collect()
    }

    fn zip_path_and_prefix<'a>(path: &'a str, prefix: &'a str) -> Vec<PrefixSeg<'a>> {
        let path_segments = Self::path_segments(path);
        let prefix_segments = Self::path_segments(prefix);
        let mut out = Vec::new();
        let max_len = path_segments.len().max(prefix_segments.len());
        for index in 0..max_len {
            match (path_segments.get(index), prefix_segments.get(index)) {
                (Some(path_segment), Some(prefix_segment)) => {
                    out.push(PrefixSeg::Both(*path_segment, *prefix_segment))
                }
                (Some(path_segment), None) => out.push(PrefixSeg::PathOnly(*path_segment)),
                (None, Some(prefix_segment)) => out.push(PrefixSeg::PrefixOnly(*prefix_segment)),
                (None, None) => break,
            }
        }
        out
    }

    fn rebuild_path_and_query(
        after_prefix: &str,
        query: Option<&str>,
    ) -> Option<http::uri::PathAndQuery> {
        let rebuilt = match (after_prefix.starts_with('/'), query) {
            (true, None) => after_prefix.parse().ok()?,
            (true, Some(query)) => format!("{}?{}", after_prefix, query).parse().ok()?,
            (false, None) => Self::ensure_absolute_path(after_prefix).parse().ok()?,
            (false, Some(query)) => {
                format!("{}?{}", Self::ensure_absolute_path(after_prefix), query)
                    .parse()
                    .ok()?
            }
        };
        Some(rebuilt)
    }

    fn replace_uri_path_and_query(
        uri: &http::Uri,
        path_and_query: http::uri::PathAndQuery,
    ) -> Option<http::Uri> {
        let mut parts = uri.clone().into_parts();
        parts.path_and_query = Some(path_and_query);
        http::Uri::from_parts(parts).ok()
    }

    fn uri_has_query(uri: &http::Uri) -> bool {
        match uri.query() {
            Some(query) if !query.is_empty() => true,
            Some(_) => false,
            None => false,
        }
    }

    fn ensure_absolute_path(path: &str) -> String {
        if path.is_empty() {
            "/".to_owned()
        } else if path.starts_with('/') {
            path.to_owned()
        } else {
            format!("/{}", path)
        }
    }

    fn split_path_and_query(path: &str) -> (&str, Option<&str>) {
        match path.split_once('?') {
            Some((path, query)) if !query.is_empty() => (path, Some(query)),
            Some((path, _)) => (path, None),
            None => (path, None),
        }
    }

    pub(super) fn apply_allow_header<ResBody>(
        res: &mut Response<ResBody>,
        allow_header: &mut Option<Bytes>,
    ) {
        match allow_header.take() {
            Some(allow_header) if !Self::header_already_has_allow(res) => {
                res.headers_mut().insert(
                    http::header::ALLOW,
                    HeaderValue::from_maybe_shared(allow_header).expect("invalid `Allow` header"),
                );
            }
            Some(_) => {}
            None => {}
        }
    }

    pub(super) fn apply_content_length<ResBody>(res: &mut Response<ResBody>)
    where
        ResBody: HttpBody,
    {
        if Self::skip_content_length_if_present(res) {
            return;
        }
        if let Some(size) = res.size_hint().exact() {
            let header_value = Self::content_length_value(size);
            res.headers_mut().insert(CONTENT_LENGTH, header_value);
        }
    }

    fn content_length_value(size: u64) -> HeaderValue {
        if size == 0 {
            #[allow(clippy::declare_interior_mutable_const)]
            const ZERO: HeaderValue = HeaderValue::from_static("0");
            ZERO
        } else {
            let mut buffer = itoa::Buffer::new();
            HeaderValue::from_str(buffer.format(size)).unwrap()
        }
    }

    fn header_already_has_allow<ResBody>(res: &http::Response<ResBody>) -> bool {
        res.headers().contains_key(http::header::ALLOW)
    }

    fn skip_content_length_if_present<ResBody>(res: &http::Response<ResBody>) -> bool {
        res.headers().contains_key(CONTENT_LENGTH)
    }
}

enum PrefixSeg<'a> {
    Both(&'a str, &'a str),
    PathOnly(&'a str),
    PrefixOnly(&'a str),

}

impl<B> Service<Request<B>> for Router<B>
where
    B: HttpBody + Send + 'static,
{
    type Response = Response;
    type Error = Infallible;
    type Future = RouteFuture<B, Infallible>;

    #[inline]
    fn poll_ready(&mut self, _: &mut Context<'_>) -> Poll<Result<(), Self::Error>> {
        Poll::Ready(Ok(()))
    }

    #[inline]
    fn call(&mut self, mut req: Request<B>) -> Self::Future {
        #[cfg(feature = "original-uri")]
        {
            use crate::extract::OriginalUri;

            if req.extensions().get::<OriginalUri>().is_none() {
                let original_uri = OriginalUri(req.uri().clone());
                req.extensions_mut().insert(original_uri);
            }
        }

        let path = req.uri().path().to_owned();

        match self.node.at(&path) {
            Ok(match_) => self.call_route(match_, req),
            Err(err) => {
                let mut fallback = match &self.fallback {
                    Fallback::Default(inner) => inner.clone(),
                    Fallback::Custom(inner) => inner.clone(),
                };

                let new_uri = match err {
                    MatchError::MissingTrailingSlash => {
                        replace_path(req.uri(), &format!("{}/", &path))
                    }
                    MatchError::ExtraTrailingSlash => {
                        replace_path(req.uri(), path.strip_suffix('/').unwrap())
                    }
                    MatchError::NotFound => None,
                };

                if let Some(new_uri) = new_uri {
                    RouteFuture::from_response(
                        Redirect::permanent(&new_uri.to_string()).into_response(),
                    )
                } else {
                    fallback.call(req)
                }
            }
        }
    }
}

fn replace_path(uri: &Uri, new_path: &str) -> Option<Uri> {
    let mut new_path_and_query = new_path.to_owned();
    if let Some(query) = uri.query() {
        new_path_and_query.push('?');
        new_path_and_query.push_str(query);
    }

    let mut parts = uri.clone().into_parts();
    parts.path_and_query = Some(new_path_and_query.parse().unwrap());

    Uri::from_parts(parts).ok()
}

/// Wrapper around `matchit::Router` that supports merging two `Router`s.
#[derive(Clone, Default)]
struct Node {
    inner: matchit::Router<RouteId>,
    route_id_to_path: HashMap<RouteId, Arc<str>>,
    path_to_route_id: HashMap<Arc<str>, RouteId>,
}

impl Node {
    fn insert(
        &mut self,
        path: impl Into<String>,
        val: RouteId,
    ) -> Result<(), matchit::InsertError> {
        let path = path.into();

        self.inner.insert(&path, val)?;

        let shared_path: Arc<str> = path.into();
        self.route_id_to_path.insert(val, shared_path.clone());
        self.path_to_route_id.insert(shared_path, val);

        Ok(())
    }

    fn at<'n, 'p>(
        &'n self,
        path: &'p str,
    ) -> Result<matchit::Match<'n, 'p, &'n RouteId>, MatchError> {
        self.inner.at(path)
    }
}

impl fmt::Debug for Node {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("Node")
            .field("paths", &self.route_id_to_path)
            .finish()
    }
}

enum Fallback<B, E = Infallible> {
    Default(Route<B, E>),
    Custom(Route<B, E>),
}

impl<B, E> Clone for Fallback<B, E> {
    fn clone(&self) -> Self {
        match self {
            Fallback::Default(inner) => Fallback::Default(inner.clone()),
            Fallback::Custom(inner) => Fallback::Custom(inner.clone()),
        }
    }
}

impl<B, E> fmt::Debug for Fallback<B, E> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Default(inner) => f.debug_tuple("Default").field(inner).finish(),
            Self::Custom(inner) => f.debug_tuple("Custom").field(inner).finish(),
        }
    }
}

impl<B, E> Fallback<B, E> {
    fn map<F, B2, E2>(self, f: F) -> Fallback<B2, E2>
    where
        F: FnOnce(Route<B, E>) -> Route<B2, E2>,
    {
        match self {
            Fallback::Default(inner) => Fallback::Default(f(inner)),
            Fallback::Custom(inner) => Fallback::Custom(f(inner)),
        }
    }
}

enum Endpoint<B> {
    MethodRouter(MethodRouter<B>),
    Route(Route<B>),
}

impl<B> Clone for Endpoint<B> {
    fn clone(&self) -> Self {
        match self {
            Endpoint::MethodRouter(inner) => Endpoint::MethodRouter(inner.clone()),
            Endpoint::Route(inner) => Endpoint::Route(inner.clone()),
        }
    }
}

impl<B> fmt::Debug for Endpoint<B> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::MethodRouter(inner) => inner.fmt(f),
            Self::Route(inner) => inner.fmt(f),
        }
    }
}

